'use strict';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
const money=n=>`₹${n.toLocaleString('en-IN')}`;
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let cart=readLocal('kodez-starch-cart',{}),wishes=readLocal('kodez-starch-wishes',[]);
if(!cart||typeof cart!=='object'||Array.isArray(cart))cart={};
cart=Object.fromEntries(Object.entries(cart).filter(([id,q])=>PRODUCTS.some(p=>p.id===+id)&&Number.isInteger(q)&&q>0).map(([id,q])=>[id,Math.min(20,q)]));
if(!Array.isArray(wishes))wishes=[];
wishes=[...new Set(wishes.filter(id=>PRODUCTS.some(p=>p.id===id)))];
let category='All',query='',sort='featured',limit=12,wishlistOnly=false,toastTimer,cartFocus;
const getProduct=id=>PRODUCTS.find(p=>p.id===+id);
function persist(){try{localStorage.setItem('kodez-starch-cart',JSON.stringify(cart));localStorage.setItem('kodez-starch-wishes',JSON.stringify(wishes))}catch{}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function counts(){const n=Object.values(cart).reduce((a,b)=>a+b,0);$('#cart-count').textContent=n;$('#drawer-count').textContent=`(${n})`;$('#wish-count').textContent=wishes.length;$('#wish-count').classList.toggle('hidden',!wishes.length);$('#wishlist-toggle').setAttribute('aria-pressed',wishlistOnly)}
function filteredProducts(){let a=PRODUCTS.filter(p=>(category==='All'||p.category===category)&&(!wishlistOnly||wishes.includes(p.id))&&`${p.name} ${p.category} ${p.pack}`.toLowerCase().includes(query.toLowerCase().trim()));if(sort==='low')a.sort((a,b)=>a.price-b.price);else if(sort==='high')a.sort((a,b)=>b.price-a.price);else if(sort==='name')a.sort((a,b)=>a.name.localeCompare(b.name));else a.sort((a,b)=>FEATURED.indexOf(a.id)-FEATURED.indexOf(b.id));return a}
function render(){const filtered=filteredProducts();$('#products').innerHTML=filtered.slice(0,limit).map((p,i)=>`<article class="product-card" style="animation-delay:${Math.min(i,7)*30}ms"><div class="product-image"><button class="view-product" data-view="${p.id}" aria-label="View ${p.name}"><img src="${p.image}" alt="${p.name}" loading="lazy" width="500" height="510"></button>${p.tag?`<span class="product-tag">${p.tag.toUpperCase()}</span>`:''}<button class="wish ${wishes.includes(p.id)?'saved':''}" data-wish="${p.id}" aria-label="${wishes.includes(p.id)?'Remove from':'Add to'} wishlist: ${p.name}" aria-pressed="${wishes.includes(p.id)}">${icon('heart')}</button><button class="quick-add" data-add="${p.id}" aria-label="Add ${p.name} to bag">${icon('plus')}</button></div><div class="product-meta"><span>${p.category}</span><span class="product-pack">${p.pack}</span></div><h3 class="product-title"><button data-view="${p.id}">${p.name}</button></h3><div class="price">${money(p.price)}<s>${money(p.oldPrice)}</s><small>${Math.round((1-p.price/p.oldPrice)*100)}% off</small></div></article>`).join('');$('#results-count').textContent=`${filtered.length} ${filtered.length===1?'festive find':'festive finds'}${wishlistOnly?' in your wishlist':''}`;$('#shown-count').textContent=filtered.length?`Showing ${Math.min(limit,filtered.length)} of ${filtered.length} little joys`:'';$('#load-more').classList.toggle('hidden',limit>=filtered.length);$('#empty-state').classList.toggle('hidden',filtered.length!==0);$('#clear-filters').classList.toggle('hidden',category==='All'&&!query&&!wishlistOnly);$('#shop-title').textContent=wishlistOnly?'Your saved little joys.':'The Diwali edit.';$$('.filter').forEach(b=>{b.classList.toggle('selected',b.dataset.category===category);b.setAttribute('aria-pressed',b.dataset.category===category)});counts()}
function selectCategory(c){category=CATEGORIES.some(x=>x.name===c)?c:'All';wishlistOnly=false;query='';$('#search').value='';limit=12;render()}
$('#category-grid').innerHTML=CATEGORIES.map(c=>`<button class="category-card" data-category-link="${c.name}"><div class="category-img"><img src="assets/${c.image}.webp" alt="${c.label}" loading="lazy"></div><strong>${c.label}</strong><small>Explore 10 finds ↗</small></button>`).join('');
$('#filters').innerHTML=['All',...CATEGORIES.map(c=>c.name)].map(c=>`<button class="filter ${c==='All'?'selected':''}" data-category="${c}" aria-pressed="${c==='All'}">${c==='All'?'All little joys':c}</button>`).join('');
$('#gift-image').src='assets/gift-round.webp';
$('#filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(b){category=b.dataset.category;limit=12;render()}});
$('#search').addEventListener('input',e=>{query=e.target.value;limit=12;render()});$('#sort').addEventListener('change',e=>{sort=e.target.value;render()});
$('#load-more').addEventListener('click',()=>{limit+=12;render()});
function reset(){category='All';query='';wishlistOnly=false;limit=12;$('#search').value='';render()}
$('#clear-filters').onclick=reset;$('#reset-shop').onclick=reset;
$('#search-toggle').onclick=()=>{$('#shop').scrollIntoView({behavior:'smooth'});$('#search').focus({preventScroll:true})};
$('#wishlist-toggle').onclick=()=>{wishlistOnly=!wishlistOnly;category='All';query='';$('#search').value='';limit=12;render();$('#shop').scrollIntoView({behavior:'smooth'})};
$('#menu-toggle').onclick=()=>{const open=$('nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',open)};
$$('nav a').forEach(a=>a.addEventListener('click',()=>{$('nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false')}));
function add(id,amount=1){if(!getProduct(id))return;const qty=(cart[id]||0)+amount;if(qty>20){toast('Maximum 20 of each item in this demo');return}cart[id]=qty;persist();counts();renderCart();toast('A little joy added to your bag')}
function toggleWish(id){id=+id;const present=wishes.includes(id);wishes=present?wishes.filter(x=>x!==id):[...wishes,id];persist();render();toast(present?'Removed from your wishlist':'Saved to your little joys')}
function openProduct(id){const p=getProduct(id);if(!p)return;$('#product-detail').innerHTML=`<div class="detail-img"><img src="${p.image}" alt="${p.name}"></div><div class="detail-copy"><p class="eyebrow">THE ${p.category.toUpperCase()} COLLECTION</p><h2>${p.name}</h2><p class="price">${money(p.price)} <s>${money(p.oldPrice)}</s></p><p>${p.description}</p><p><strong>Pack:</strong> ${p.pack}<br>Photos are illustrative; pack variants may share an image.</p><button class="button primary" data-add="${p.id}">Add to festive bag ${icon('bag')}</button><small>Demo product & price · No payment will be taken</small></div>`;$('#product-dialog').showModal()}
function totals(){const subtotal=Object.entries(cart).reduce((sum,[id,n])=>sum+getProduct(id).price*n,0);return{subtotal,total:subtotal}}
function renderCart(){counts();const entries=Object.entries(cart);$('#cart-items').innerHTML=entries.length?entries.map(([id,n])=>{const p=getProduct(id);return`<div class="cart-line"><img src="${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>${p.pack} · ${money(p.price)}</p><div class="line-bottom"><div class="quantity"><button data-qty="${id}" data-change="-1" aria-label="Decrease quantity of ${p.name}">−</button><span>${n}</span><button data-qty="${id}" data-change="1" aria-label="Increase quantity of ${p.name}" ${n>=20?'disabled':''}>+</button></div><strong>${money(p.price*n)}</strong><button class="remove" data-remove="${id}">Remove</button></div></div></div>`}).join(''):`<div class="empty-bag"><span>✧</span><h3>Room for a little joy.</h3><p>Your festive bag is waiting.<br>Find something that lights up your world.</p><button class="button primary" data-shop>Explore the collection ↗</button></div>`;const t=totals();$('#cart-summary').innerHTML=entries.length?`<div class="summary-line"><span>Subtotal</span><span>${money(t.subtotal)}</span></div><div class="summary-line"><span>Delivery</span><span>Not applicable · demo</span></div><div class="summary-line total"><span>Total</span><strong>${money(t.total)}</strong></div><button class="button primary checkout-btn" id="checkout-button">Preview checkout <span>↗</span></button><p class="demo-note">A demo bag full of joy. No payment or real order.</p>`:''}
function openCart(){cartFocus=document.activeElement;renderCart();$('#cart-drawer').hidden=false;$('#drawer-overlay').hidden=false;document.body.classList.add('locked');$('#close-cart').focus()}
function closeCart(){if($('#cart-drawer').hidden)return;$('#cart-drawer').hidden=true;$('#drawer-overlay').hidden=true;document.body.classList.remove('locked');cartFocus?.focus()}
$('#cart-toggle').onclick=openCart;$('#close-cart').onclick=closeCart;$('#drawer-overlay').onclick=closeCart;
function checkout(){if(!Object.keys(cart).length)return;closeCart();const t=totals();$('#checkout-content').innerHTML=`<p class="eyebrow">A LITTLE PREVIEW OF THE JOY</p><h2>Your celebration, together.</h2><p>This is a frontend store demo. No real order is placed, no payment is collected and no products are shipped.</p><ul class="checkout-list">${Object.entries(cart).map(([id,n])=>`<li><span>${getProduct(id).name} × ${n}</span><strong>${money(getProduct(id).price*n)}</strong></li>`).join('')}</ul><div class="summary-line total"><span>Demo total</span><strong>${money(t.total)}</strong></div><button class="button primary" id="complete-demo">Complete demo checkout ↗</button>`;$('#checkout-dialog').showModal()}
function completeDemo(){cart={};persist();counts();renderCart();$('#checkout-content').innerHTML=`<span class="success-icon">✺</span><p class="eyebrow">A MOMENT OF FESTIVE JOY</p><h2>Your demo is complete.</h2><p>Thanks for exploring Kodez Starch. Your demo bag has been cleared. No order was placed and no payment was taken.</p><button class="button primary" data-close>Keep exploring ↗</button>`}
async function info(title){$('#info-content').innerHTML=`<p class="eyebrow">KODEZ STARCH</p><h2>${title}</h2>`;if(title==='Image credits'){$('#info-content').insertAdjacentHTML('beforeend','<p>Internet-sourced product photographs used as illustrative demo assets. Images belong to their respective creators and retailers. Confirm reuse permissions before commercial publication. Pack variants may share a representative image.</p><div id="credits-list">Loading credits…</div>');try{const data=await fetch('asset-sources.json').then(r=>r.json());const arr=Array.isArray(data)?data:(data.assets||Object.values(data));$('#credits-list').replaceChildren();const ul=document.createElement('ul');ul.className='credits';for(const entry of arr){if(!entry||typeof entry!=='object')continue;const url=entry.source_url||entry.url||entry.original_url||entry.image_url;const li=document.createElement('li');if(url&&/^https?:\/\//.test(url)){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=entry.filename||entry.file||entry.name||new URL(url).hostname;li.append(a)}else li.textContent=JSON.stringify(entry);ul.append(li)}$('#credits-list').append(ul)}catch{$('#credits-list').textContent='Image sources are included with the site in asset-sources.json.'}}else if(title==='Delivery & returns'){$('#info-content').insertAdjacentHTML('beforeend','<p>This is a demonstration storefront. Delivery, fulfilment, returns and refunds are not available. All prices and product packs are sample catalogue data.</p><p>For a real store, delivery regions, inventory, product specifications and return policies need to be supplied by the merchant.</p>')}else{$('#info-content').insertAdjacentHTML('beforeend','<p>Kodez Starch is a Diwali shopping experience created for Krishna Kodez, with 60 sample products across six festive collections.</p><p>Your cart and wishlist are stored only in this browser. There is no backend, account registration, payment processing or real ordering. Clear your browser site data to remove saved selections.</p>')}$('#info-dialog').showModal()}
document.addEventListener('click',e=>{let b;if(b=e.target.closest('[data-add]'))add(+b.dataset.add);else if(b=e.target.closest('[data-wish]'))toggleWish(+b.dataset.wish);else if(b=e.target.closest('[data-view]'))openProduct(+b.dataset.view);else if(b=e.target.closest('[data-category-link]')){selectCategory(b.dataset.categoryLink);$('#shop').scrollIntoView({behavior:'smooth'})}else if(b=e.target.closest('[data-select]'))selectCategory(b.dataset.select);else if(b=e.target.closest('[data-qty]')){const id=b.dataset.qty;cart[id]=(cart[id]||0)+Number(b.dataset.change);if(cart[id]<=0)delete cart[id];persist();renderCart()}else if(b=e.target.closest('[data-remove]')){delete cart[b.dataset.remove];persist();renderCart()}else if(e.target.closest('[data-shop]')){closeCart();$('#shop').scrollIntoView({behavior:'smooth'})}else if(e.target.closest('#checkout-button'))checkout();else if(e.target.closest('#complete-demo'))completeDemo();else if(b=e.target.closest('[data-close]'))b.closest('dialog').close();else if(b=e.target.closest('[data-info]'))info(b.dataset.info)});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeCart();if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!$('dialog[open]')&&$('#cart-drawer').hidden){e.preventDefault();$('#search-toggle').click()}if(e.key==='Tab'&&!$('#cart-drawer').hidden){const els=$$('button,a,input,select', $('#cart-drawer')).filter(x=>!x.disabled&&x.offsetParent!==null),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){document.documentElement.classList.add('motion');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target)}}),{threshold:.1});$$('.reveal').forEach(e=>observer.observe(e))}
render();renderCart();
